-- Master Data "Harga Jual per Item" -- seed SEKALI KALI dari "Item Library (Tigalapan).csv"
-- (2026-09-13, 2.139 baris, 6 kategori yang benar-benar dipakai alur MRP di app ini: COMBED 24S,
-- COMBED 30S, KIDS 24S, PANJANG + RIB, TUNIK 24S, WANGKI MYNO), dipakai untuk menghitung kolom
-- "% HPP" di Laporan HPP (Finance) -- HPP/Item dibagi Harga Jual/Item x 100%. BUKAN Master Data
-- live: TIDAK ADA CRUD/tombol import ulang/panel edit di app -- kalau harga berubah, perlu
-- migration baru atau UPDATE manual lewat SQL Editor Supabase. `sku` boleh null (482 dari 2139
-- baris tidak punya SKU di file sumber), `price` boleh 0 (13 baris harga kosong di file sumber,
-- sengaja diisi 0 bukan error). `warna`/`lengan`/`size` mengikuti format PERSIS yang sudah dipakai
-- live di `lengan_groups.warna`/`lengan` (lihat lib/mrp/derive.ts sellingPriceFor -- matching EXACT
-- case-sensitive tanpa trim, sama pola `ekspedisiPrice`).
create table item_selling_prices (
  id text primary key,
  kategori text not null,
  sku text,
  item_name text not null,
  warna text not null,
  lengan text not null,
  size text not null,
  price numeric not null default 0
);

-- Index untuk lookup cepat oleh sellingPriceFor (warna+lengan+size).
create index item_selling_prices_warna_lengan_size_idx on item_selling_prices (warna, lengan, size);

-- RLS: sama pola tabel master data lain (ekspedisi_rates di 0034 dst) -- aktif, TANPA policy
-- tambahan (default deny untuk anon/authenticated, service role selalu bypass).
alter table item_selling_prices enable row level security;

-- Seed 2.139 baris dari .pipeline/item_selling_prices_values.sql (sudah divalidasi supervisor:
-- 0 duplikat kunci warna+lengan+size, 0 baris gagal parse) -- dipakai APA ADANYA, tidak di-generate
-- ulang dari CSV mentah.
